//! The guest ABI range the kernel's Programs module admits.
//!
//! `MAX_VERSION` is generated by the crate build script from the
//! `LX_PROGRAMS_GUEST_ABI_V*_VERSION` enumerators of
//! `include/layerx/programs.h`, so the encoders here admit exactly the versions
//! the kernel admits and never a second hand-written bound.

include!(concat!(env!("OUT_DIR"), "/guest_abi.rs"));

/// Reports whether the kernel admits `version` as a program's guest ABI.
///
/// The kernel refuses a zero version and every version above the highest
/// enumerator `include/layerx/programs.h` allocates.
#[must_use]
pub const fn supported(version: u16) -> bool {
    version != 0 && version <= MAX_VERSION
}

#[cfg(test)]
mod tests {
    use super::{supported, MAX_VERSION};

    const PROGRAMS_HEADER: &str = include_str!("../../../../include/layerx/programs.h");

    fn header_maximum() -> u16 {
        let mut maximum = 0;
        for line in PROGRAMS_HEADER.lines() {
            let Some(rest) = line.trim().strip_prefix("LX_PROGRAMS_GUEST_ABI_V") else {
                continue;
            };
            let (declared, value) = rest
                .split_once("_VERSION = ")
                .unwrap_or_else(|| panic!("unexpected guest ABI enumerator: {line}"));
            let value: u16 = value
                .trim_end_matches(',')
                .trim()
                .parse()
                .unwrap_or_else(|error| panic!("invalid guest ABI number in {line}: {error}"));
            assert_eq!(
                declared.parse::<u16>().ok(),
                Some(value),
                "guest ABI enumerator {line} names a version it does not equal"
            );
            maximum = maximum.max(value);
        }
        assert!(
            maximum >= 2,
            "include/layerx/programs.h declares no guest ABI enumerator"
        );
        maximum
    }

    #[test]
    fn max_version_is_the_kernel_headers_highest_guest_abi() {
        assert_eq!(MAX_VERSION, header_maximum());
    }

    #[test]
    fn supported_admits_exactly_the_kernels_range() {
        assert!(!supported(0));
        for version in 1..=MAX_VERSION {
            assert!(supported(version), "{version}");
        }
        assert!(!supported(MAX_VERSION + 1));
        assert!(!supported(u16::MAX));
    }
}
